def dijkstra(graph: dict, start: str, end: str) -> int:
    pq = [(0, start)]
    distances = {start: 0}
    while pq:
        dist, node = heapq.heappop(pq)
        if node == end:
            return dist
        if dist > distances.get(node, float('inf')):
