import sys

def longest_stable_window(readings: list[int], limit: int) -> int:
    from collections import deque
    min_dq = deque()
    max_dq = deque()
    left = 0
    ans = 0
    for right, val in enumerate(readings):
        while min_dq and readings[min_dq[-1]] >= val:
            min_dq.pop()
        while max_dq and readings[max_dq[-1]] <= val:
            max_dq.pop()
        min_dq.append(right)
        max_dq.append(right)
        while readings[max_dq[0]] - readings[min_dq[0]] > limit:
            left += 1
            if min_dq[0] < left:
                min_dq.popleft()
            if max_dq[0] < left:
                max_dq.popleft()
        ans = max(ans, right - left + 1)
    return ans

